/**
 * Private document storage. Implementations must never make objects publicly
 * readable; Phase 2 adds short-lived, authorised read access for staff.
 */
export interface DocumentStorage {
  put(key: string, bytes: Uint8Array, contentType: string): Promise<void>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server only; this guards against path tricks regardless. */
export const STORAGE_KEY_PATTERN = /^[a-z0-9-]+\/[0-9a-f-]{36}\.(pdf|jpg|png)$/;

export function assertSafeKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new Error("Unsafe storage key");
}
